mapper.select:
select oi.order_id as orderId,oi.order_begin_date as orderBeginDate,oi.order_end_date as orderEndDate,oi.waiter_id as waiterId,oi.table_id as tableId,oi.price as price,u.user_id as userId,u.user_name as userName,d.dishes_id as dishesId,d.dishes_name as dishesName from order_info oi inner join order_dishes od on oi.order_id = od.order_reference inner join dishes d on od.dishes=d.dishes_id inner join user_info u on oi.waiter_id = u.user_id


    oi.waiter_id like concat('%',#{param1,jdbcType=VARCHAR},'%')


    and oi.table_id = #{param2}


    and oi.order_begin_date between(#{param3,jdbcType=TIMESTAMP},#{param4,jdbcType=TIMESTAMP})


    and oi.order_begin_date >= #{param3,jdbcType=TIMESTAMP}


    and oi.order_end_date <= #{param4,jdbcType=TIMESTAMP}
